import base64

# 1. Paste your full string here
encoded_str = """"""

# 2. Base64 Decode -> Morse Code
morse_str = base64.b64decode(encoded_str).decode('utf-8')

# 3. Morse Code -> Binary (----- = 0, .---- = 1)
binary_str = "".join(['0' if word == "-----" else '1' for word in morse_str.split()])

# 4. Binary -> Intermediate Text
intermediate_chars = [chr(int(binary_str[i:i+8], 2)) for i in range(0, len(binary_str), 8)]
intermediate_text = "".join(intermediate_chars)

# 5. Offset Cipher -> Final Flag
# The intermediate text is space-separated. Each block represents an ASCII character.
# The characters in the block are offset by 95 (e.g., '_' = 0, '`' = 1, 'a' = 2, 'b' = 3...)
final_flag = ""
for block in intermediate_text.split(" "):
    if not block: continue
    
    # Extract the decimal digits by subtracting 95 from the ASCII value
    num_str = "".join([str(ord(c) - 95) for c in block])
    
    # Convert the reconstructed decimal number back to a final character
    final_flag += chr(int(num_str))

print("\n[+] Extraction Complete! Here is the decoded message:")
print(final_flag)